package com.denzic.companion.app;
import java.nio.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.io.*;

/** Generated PCM only. No Owner recording, device, model or Android app. */
public final class CanonicalPcmRendererTest {
 static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
 static String hash(Path p)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(p)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static Path wav(Path root,String name,int first,int count)throws Exception{ByteBuffer b=ByteBuffer.allocate(44+count*2).order(ByteOrder.LITTLE_ENDIAN);b.put(new byte[]{'R','I','F','F'}).putInt(36+count*2).put(new byte[]{'W','A','V','E','f','m','t',' '}).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put(new byte[]{'d','a','t','a'}).putInt(count*2);for(int i=0;i<count;i++)b.putShort((short)(first+i));Path p=root.resolve(name);Files.write(p,b.array(),StandardOpenOption.CREATE_NEW);return p;}
 static CanonicalPcmRenderer.Input input(String key,char identity,Path...paths)throws Exception{List<String> hashes=new ArrayList<>();for(Path p:paths)hashes.add(hash(p));char[] chars=new char[64];Arrays.fill(chars,identity);return new CanonicalPcmRenderer.Input(key,new String(chars),Arrays.asList(paths),hashes);}
 interface Failing {void run()throws Exception;}
 static long count(Path p)throws Exception{try(java.util.stream.Stream<Path> files=Files.list(p)){return files.count();}}
 static void failsWithoutOutput(Path stage,Failing action,String contains)throws Exception{long before=count(stage);try{action.run();throw new AssertionError("Expected rejection: "+contains);}catch(IOException expected){require(expected.getMessage().contains(contains),expected.toString());}require(before==count(stage),"Failed operation left a new output");}
 public static void main(String[] args)throws Exception{
  require(args.length==1,"Explicit new owned test root required");Path root=Paths.get(args[0]).toAbsolutePath().normalize();require(!Files.exists(root),"Never overwrite a previous case");Files.createDirectories(root);Path stage=root.resolve("stage");Files.createDirectory(stage);
  Path a1=wav(root,"generated-a1.wav",0,10),a2=wav(root,"generated-a2.wav",10,7),b=wav(root,"generated-b.wav",1000,16);String beforeA1=hash(a1),beforeA2=hash(a2),beforeB=hash(b);CanonicalPcmRenderer.Input first=input("first-original",'a',a1,a2),second=input("second-original",'b',b);CanonicalPcmRenderer.Control go=(done,total)->{};
  List<CanonicalPcmRenderer.Clip> clips=Arrays.asList(new CanonicalPcmRenderer.Clip(first,8,15),new CanonicalPcmRenderer.Clip(second,1,5),new CanonicalPcmRenderer.Clip(first,0,3));CanonicalPcmRenderer.Result result=CanonicalPcmRenderer.render(stage,clips,go);require(result.frames==14&&result.bytes==72,"Incorrect exact output length");require(hash(result.temporary).equals(result.sha256),"Output digest mismatch");ByteBuffer out=ByteBuffer.wrap(Files.readAllBytes(result.temporary)).order(ByteOrder.LITTLE_ENDIAN);require(out.getInt(4)==64&&out.getInt(40)==28,"Invalid WAV header");int[] expected={8,9,10,11,12,13,14,1001,1002,1003,1004,0,1,2};for(int i=0;i<expected.length;i++)require(out.getShort(44+i*2)==expected[i],"Wrong PCM at "+i);
  CanonicalPcmRenderer.Result complete=CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(first,0,17)),go);require(complete.frames==17,"Last partial millisecond dropped");require(ByteBuffer.wrap(Files.readAllBytes(complete.temporary)).order(ByteOrder.LITTLE_ENDIAN).getShort(44+16*2)==16,"Last source sample changed");
  failsWithoutOutput(stage,()->CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(first,-1,5)),go),"区间");failsWithoutOutput(stage,()->CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(first,0,18)),go),"区间");failsWithoutOutput(stage,()->CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(first,5,5)),go),"区间");
  CanonicalPcmRenderer.Input badHash=new CanonicalPcmRenderer.Input("wrong-original",new String(new char[64]).replace('\0','c'),Arrays.asList(a1),Arrays.asList(new String(new char[64]).replace('\0','0')));failsWithoutOutput(stage,()->CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(badHash,0,5)),go),"原件已变化");
  Path malformed=root.resolve("malformed-only-test-copy.wav");byte[] raw=Files.readAllBytes(a1);raw[20]=3;Files.write(malformed,raw,StandardOpenOption.CREATE_NEW);CanonicalPcmRenderer.Input badFormat=input("bad-format",'d',malformed);failsWithoutOutput(stage,()->CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(badFormat,0,5)),go),"16kHz");
  Path shortFile=root.resolve("truncated-only-test-copy.wav");Files.write(shortFile,Arrays.copyOf(Files.readAllBytes(a1),45),StandardOpenOption.CREATE_NEW);CanonicalPcmRenderer.Input truncated=input("short-file",'e',shortFile);failsWithoutOutput(stage,()->CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(truncated,0,1)),go),"完整WAV");
  Path large=wav(root,"generated-large-cancel.wav",2000,100000);String largeHash=hash(large);CanonicalPcmRenderer.Input big=input("big-generated",'f',large);failsWithoutOutput(stage,()->CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(big,0,100000)),(done,total)->{if(done>0)throw new IOException("已取消编辑");}),"取消");require(hash(large).equals(largeHash),"Cancellation changed its source");
  Path changing=root.resolve("intentional-mutation-only-test-copy.wav");Files.copy(large,changing);CanonicalPcmRenderer.Input mutable=input("mutable-test-copy",'a',changing);boolean[] changed={false};failsWithoutOutput(stage,()->CanonicalPcmRenderer.render(stage,Arrays.asList(new CanonicalPcmRenderer.Clip(mutable,0,100000)),(done,total)->{if(done>0&&!changed[0]){changed[0]=true;try(java.nio.channels.FileChannel channel=java.nio.channels.FileChannel.open(changing,StandardOpenOption.WRITE)){channel.position(Files.size(changing)-2);channel.write(ByteBuffer.wrap(new byte[]{1,2}));channel.force(true);}}}),"编辑期间发生变化");require(changed[0],"Mutation guard was not triggered");
  require(hash(a1).equals(beforeA1)&&hash(a2).equals(beforeA2)&&hash(b).equals(beforeB),"An original fixture changed");require(count(stage)==2,"Only the two completed outputs should remain");System.out.println("PASS actual bounded PCM rendering: multipart and reordered multiple sources, exact WAV/samples/SHA, full last sample, invalid ranges/hash/format/truncation, mid-write cancel cleanup, and source mutation rejection. Native service/store/UI not yet wired.");
 }
}
